select left(stem,110) from questions q join subject_groups g on g.id=q.subject_group_id where g.code='statistics' and (stem ilike '%harmonic%' or stem ilike '%average speed%' or stem ilike '%kurtosis%' or stem ilike '%peaked%' or stem ilike '%arrange%' or stem ilike '%3X%' or stem ilike '%false positive%' or stem ilike '%upper quartile%' or stem ilike '%P(X = 0)%' or stem ilike '%P(X=0)%');
